 "content": "def transform(grid):
    # A solid separator divides repeated panels; copy the populated panel
    # into the corresponding blank/background panel.
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    horizontal = [r for r in range(h) if len(set(g[r])) == 1 and g[r][0] != 0]
    vertical = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1 and g[0][c] != 0]
    if horizontal and not vertical:
        r = horizontal[0]
        top, bottom = g[:r], g[r+1:]
        if len(top) == len(bottom):
            src = bottom if any(v != top[0][0] for row in bottom for v in row) else top
            return [row[:] for row in src] + [g[r][:]] + [row[:] for row in src]
    if horizontal and vertical:
        r, c = horizontal[0], vertical[0]
        source = [row[:c] for row in g[:r]]
        out = [[0]*w for _ in range(h)]
        for i in range(h):
            for j in range(w):
                if i == r or j == c:
                    out[i][j] = g[i][j]
                else:
                    out[i][j] = source[i % r][j % c]
        return out
    return g

if __name__ == '__main__':
    test = [[5,5,5],[5,5,5],[8,8,8],[7,7,5],[5,4,5]]
